-- Native goal editing, shared projections and real canonical season close.
insert into app.seasons(id,tenant_id,name,starts_on,ends_on,winter_cutoff_at,status)values('ad180000-0000-4000-8000-000000000001','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','Synthetic historical close','2024-07-01','2025-06-30','2024-12-21+01','active');
create function pg_temp.actor(uid uuid)returns void language plpgsql as $$begin perform set_config('request.jwt.claims',jsonb_build_object('sub',uid,'session_id',uid)::text,true);end;$$;
set local role authenticated;select pg_temp.actor('33333333-3333-4333-8333-333333333333');
select lives_ok($$select api.pwa_command('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','set_team_goal','ad160000-0000-4000-8000-000000000003',0,'{"season_id":"ad180000-0000-4000-8000-000000000001","goal":0,"reason":"Initial zero agreement"}','ad186000-0000-4000-8000-000000000001')$$,'zero is an actual native team agreement');
select lives_ok($$select api.pwa_command('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','set_team_goal','ad160000-0000-4000-8000-000000000003',1,'{"season_id":"ad180000-0000-4000-8000-000000000001","goal":2,"reason":"Explicit new two-place agreement"}','ad186000-0000-4000-8000-000000000002')$$,'native amendment retains previous agreement');
select is((api.club_admin_read('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','teams','ad180000-0000-4000-8000-000000000001','ad160000-0000-4000-8000-000000000003')->'rows'->0->'goals'->0->'agreement_history'->0->>'goal')::integer,0,'administrative history retains exact prior zero');
select is(api.club_admin_read('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','report_teams','ad180000-0000-4000-8000-000000000001')->'rows'->0->>'goal_total','4','shared team projection sums two member goals');
select lives_ok($$select api.close_season('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','ad180000-0000-4000-8000-000000000001',1,'ad186000-0000-4000-8000-000000000003')$$,'original native season close captures team measurement');
select is(api.club_admin_read('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','report_teams','ad180000-0000-4000-8000-000000000001')->'rows'->0->>'goal_total','4','closed report reads captured team agreement');
select lives_ok($$select api.close_season('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','ad180000-0000-4000-8000-000000000001',1,'ad186000-0000-4000-8000-000000000003')$$,'same close command is replayed without a second snapshot');
select throws_ok($$select api.pwa_command('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','set_team_goal','ad160000-0000-4000-8000-000000000003',2,'{"season_id":"ad180000-0000-4000-8000-000000000001","goal":3}','ad186000-0000-4000-8000-000000000004')$$,'22023','INVALID_SEASON','closed native team agreement is frozen');
